"""Collect licenses for dependencies pinned in go.mod from the Go module cache."""
import json
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[1]


def main():
    metadata = json.loads(subprocess.check_output(['go', 'mod', 'edit', '-json'], cwd=ROOT))
    sections = ['Third-party notices for dependencies pinned in go.mod.\n'
                'Generated by scripts/update_notices.py; dependency licenses follow.\n']
    for dependency in metadata['Require']:
        name = dependency['Path']
        module = json.loads(subprocess.check_output(['go', 'list', '-m', '-json', name], cwd=ROOT))
        if 'Dir' not in module:
            raise SystemExit(f'Run go mod download first: {name}')
        directory = Path(module['Dir'])
        files = [p for p in directory.iterdir() if p.is_file() and
                 p.name.upper().split('.')[0] in {'LICENSE', 'LICENCE', 'NOTICE', 'COPYING', 'COPYRIGHT'}]
        if name == 'fyne.io/fyne/v2':
            files.extend((directory / 'theme/font').glob('LICENSE*'))
        if not files:
            raise SystemExit(f'No license found for {name}')
        sections.append(f'\n{"=" * 72}\n{name} {module["Version"]}\n')
        for path in sorted(files):
            sections.append(f'\n--- {path.relative_to(directory)} ---\n')
            sections.append('\n'.join(line.rstrip() for line in path.read_text(encoding='utf-8').splitlines()).rstrip() + '\n')
    output = ROOT / 'licenses/THIRD_PARTY_NOTICES.txt'
    output.write_text(''.join(sections), encoding='utf-8')
    print(f'Collected notices for {len(metadata["Require"])} pinned dependencies: {output}')


if __name__ == '__main__':
    main()
